// Define the Karplus-Strong plucked-string synthesis
karplusStrong = (f, d, t) -> {
  // Define the delay line with a two-point averaging low-pass in the feedback loop
  delayLine = (x, y) -> {
    // Two-point averaging low-pass
    lowPass = (a, b) -> (a + b) / 2;
    // Delay line with two-point averaging
    delay = (x, y) -> lowPass(x, y);
    // Feedback loop with two-point averaging
    feedback = (x, y) -> delay(x, y) * d;
    // Trigger gate
    trigger = (x, y) -> (x > 0) ? y : 0;
    // Main loop
    return (x, y) -> trigger(x, feedback(x, y));
  };

  // Initialize the delay line with a random value
  init = (x, y) -> (x > 0) ? x : os.noise();
  // Main loop with trigger gate
  return (x, y) -> init(x, delay(x, y));
};

