// LFO function
lfo(f) = os.lf_triangle(f) * 0.5 + 0.5;

// Delay function
delay(n, d) = de.fdelay(n, d);

// Cross delay function
crossL(fbL, fbR, inL, inR) = inL + fbR * fbL;
crossR(fbL, fbR, inL, inR) = inR + fbL * fbR;

// Chorus function
