  crossL(fbL, fbR, inL, inR) = inL + fbR * fbL;
  crossR(fbL, fbR, inL, inR) = inR + fbL * fbR;

  // Dry and wet mix
  dry = par(i, 2, _ * (1 - mix));
  wet = (crossL ~ (delay(delay_time_left, delay_time_left), delay(delay_time_right, delay_time_right))) : par(i, 2, _ * mix);
};

