import("stdfaust.lib");

// Parameters
MAXD  = 1024;
freq   = hslider("Frequency [unit:Hz]", 440, 20, 20000, 1) : si.smoo;
decay  = hslider("Decay [unit:ms]", 10, 1, 1000, 1) : *(0.001);
feedback = hslider("Feedback", 0.4, 0, 0.95, 0.01) : si.smoo;

// Initialize the buffer
buffer = si.bus(MAXD);

// Karplus-Strong algorithm
karplusStrong(x) = (buffer :> x) * (1 - feedback) + (buffer : min(MAXD-1) : max(1)) * feedback;

// Process function
process = karplusStrong, karplusStrong;

