import("stdfaust.lib");

// Karplus-Strong plucked string synthesizer
MAXD = 4096;
freq = hslider("Frequency [unit:Hz]", 440, 20, 20000, 1) : si.smoo;
decay = hslider("Decay [unit:ms]", 10, 1, 1000, 1) : *(0.001);
delay = hslider("Delay [unit:ms]", 10, 1, 1000, 1) : *(0.001) : min(MAXD-1) : max(1);

// Initialize the string with a single sample
string = 0.0;

process = string with {
  // Calculate the next sample
  nextSample = string * decay + (string : (+ : de.fdelay(MAXD, delay))) * 0.5;
  // Update the string with the next sample
  string = nextSample;
};

