import("stdfaust.lib");

// Karplus-Strong plucked string synthesizer
// Parameters
MAXD  = 1024;
freq   = hslider("Frequency [unit:Hz]", 440, 20, 20000, 1) : si.smoo;
decay  = hslider("Decay [unit:ms]", 10, 1, 1000, 1) : *(0.001);
feedback = hslider("Feedback", 0.4, 0, 0.95, 0.01) : si.smoo;

// Initialize the buffer
buffer = si.bus(MAXD);

// Process function
process = (x, y) with {
  // Update the buffer with the current sample and feedback
  buffer = buffer <: x + feedback * buffer[0];
  // Output the current sample from the buffer
  y = buffer[0];
};

// Apply the process to both channels
process = par(i, 2, process);

